import{_ as t,o as e,c as i,a2 as a}from"./chunks/framework.BYgiQ6KE.js";const n="/angular-tutorial-site/assets/EP.15-security-boundary.BMevw5jn.svg",u=JSON.parse('{"title":"EP.15 信任边界","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.15-security-boundary.md","filePath":"comics/EP.15-security-boundary.md","lastUpdated":1793863170000}'),o={name:"comics/EP.15-security-boundary.md"};function r(d,s,l,c,h,p){return e(),i("div",null,[...s[0]||(s[0]=[a('<h1 id="ep-15-信任边界" tabindex="-1">EP.15 信任边界 <a class="header-anchor" href="#ep-15-信任边界" aria-label="Permalink to &quot;EP.15 信任边界&quot;">​</a></h1><p><img src="'+n+`" alt="EP.15 信任边界"></p><blockquote><p>对应正文：<a href="./../guide/part7/15-security">15-security</a>（1 信任边界 / 2 自动净化 / 4 CSP / 5 Trusted Types / 8 常见坑）· 配套示例：<code>i18n-a11y</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君把用户评论直接交给 <code>bypassSecurityTrustHtml</code>，评论里的 <code>&lt;img onerror&gt;</code> 被执行，页面弹窗。</li><li><strong>第 2 格</strong>：码叔画出信任边界——用户输入、接口、URL 都不可信；HTML、URL、STYLE、SCRIPT 各有对应的净化 context。</li><li><strong>第 3 格</strong>：像素酱对照两条路径：<code>sanitize</code> 保留 <code>&lt;b&gt;</code>、移除 <code>onerror</code> 与 <code>&lt;script&gt;</code>；<code>bypass</code> 则原样保留并执行。</li><li><strong>第 4 格</strong>：码叔结案——<strong>文本用插值、HTML 用净化、bypass 只给可信来源</strong>；CSP 与 Trusted Types 是第二道、第三道防线。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-信任边界不是字符过滤" tabindex="-1">第 1 格 · 信任边界不是字符过滤 <a class="header-anchor" href="#第-1-格-·-信任边界不是字符过滤" aria-label="Permalink to &quot;第 1 格 · 信任边界不是字符过滤&quot;">​</a></h3><p>来自用户、URL、接口、第三方脚本的数据都属于不可信输入；模板静态文案才可信。不可信数据进 DOM 前必须净化或验证：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">protected readonly safeHtml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sanitizer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sanitize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SecurityContext.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HTML</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rawHtml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">??</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>&lt;b&gt;</code> 会保留，<code>onerror</code> 会被移除。</p><h3 id="第-2-格-·-context-必须与输出位置匹配" tabindex="-1">第 2 格 · context 必须与输出位置匹配 <a class="header-anchor" href="#第-2-格-·-context-必须与输出位置匹配" aria-label="Permalink to &quot;第 2 格 · context 必须与输出位置匹配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>SecurityContext</th><th>用途</th><th>典型输出</th></tr></thead><tbody><tr><td><code>HTML</code></td><td>富文本片段</td><td>移除脚本、事件属性与危险标签</td></tr><tr><td><code>URL</code></td><td><code>href</code> / <code>src</code></td><td>危险协议变为 <code>unsafe:</code></td></tr><tr><td><code>STYLE</code></td><td>内联样式</td><td>移除危险 CSS 表达式</td></tr><tr><td><code>SCRIPT</code></td><td>脚本内容</td><td>仅允许可信脚本</td></tr></tbody></table><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sanitizer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sanitize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SecurityContext.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;javascript:alert(1)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>用 <code>HTML</code> 的规则处理 URL，<code>javascript:</code> 链接仍然可点击。</p><h3 id="第-3-格-·-bypass-是声明-不是能力" tabindex="-1">第 3 格 · bypass 是声明，不是能力 <a class="header-anchor" href="#第-3-格-·-bypass-是声明-不是能力" aria-label="Permalink to &quot;第 3 格 · bypass 是声明，不是能力&quot;">​</a></h3><p><code>bypassSecurityTrust*</code> 会跳过净化，只应出现在两种场景：内容来自完全可信的后端富文本服务，或已由独立净化库（如 DOMPurify）处理。即便如此，也要满足来源可追溯、规则持续更新、输出点有审计。</p><p>把 <code>bypassSecurityTrustHtml</code> 用在用户评论、昵称、聊天消息上，等同于关闭 XSS 防护。</p><h3 id="第-4-格-·-csp-与-trusted-types" tabindex="-1">第 4 格 · CSP 与 Trusted Types <a class="header-anchor" href="#第-4-格-·-csp-与-trusted-types" aria-label="Permalink to &quot;第 4 格 · CSP 与 Trusted Types&quot;">​</a></h3><p>净化解决「恶意内容进入 DOM」，CSP 解决「即使脚本进来了也别执行」：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Security-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  default-src &#39;self&#39;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  script-src &#39;self&#39;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  object-src &#39;none&#39;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  base-uri &#39;self&#39;;</span></span></code></pre></div><p>Trusted Types 进一步要求危险 sink 只接受经过策略创建的 <code>TrustedHTML</code>。落地顺序：先 <code>Report-Only</code> 收集违规，再启用 <code>require-trusted-types-for &#39;script&#39;</code>，最后把第三方库逐个纳入策略。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../guide/part7/15-security#8-常见坑">常见坑表格</a></p></blockquote><ol><li>对用户评论用 <code>bypassSecurityTrustHtml</code> → <strong>等同关闭 XSS 防护，改用 <code>sanitize</code> 或 DOMPurify</strong>；</li><li>URL 绑定用 HTML context → <strong><code>javascript:</code> 仍可点击，必须用 <code>SecurityContext.URL</code></strong>；</li><li>CSP 一次性收得太死 → <strong>生产白屏，先用 <code>Report-Only</code> 收集再收紧</strong>；</li><li>自定义指令直接拼 DOM 字符串 → <strong>绕过 Trusted Types，通过策略创建 <code>TrustedHTML</code></strong>；</li><li>SSR 场景拼接用户数据 → <strong>服务端绕过模板转义，必须复用同一套净化逻辑</strong>。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>为什么「过滤坏字符」不足以防护 XSS？——<strong>攻击向量不止字符，还包括协议、属性与 DOM sink；正确做法是划清信任边界，按输出位置选择净化 context，并配合 CSP 与 Trusted Types</strong>。</li><li><code>SecurityContext.URL</code> 与 <code>SecurityContext.HTML</code> 有什么不同？——<strong>HTML 规则针对富文本片段，移除脚本与事件属性；URL 规则针对 <code>href</code> / <code>src</code>，把危险协议替换为 <code>unsafe:</code>。用错 context 会让危险 URL 通过</strong>。</li><li>Trusted Types 解决的是什么问题？——<strong>它把 <code>innerHTML</code> 等危险 sink 限制为只接受策略创建的 <code>TrustedHTML</code>，让「忘记净化」从静默执行变成运行时错误</strong>。</li></ol>`,26)])])}const y=t(o,[["render",r]]);export{u as __pageData,y as default};
